SourceCode.Declaration:
/// <summary>
/// The attribute to add if the adhoc action should appear on the 'adhoc' menu items in the add menu item lookup page.
/// </summary>
class TFMPageLineAdhocRequestAttribute extends SysAttribute implements SysExtensionIAttribute
{
    MethodName			methodName;
    Name				title;
    ResourceName		icon;
    boolean				refreshOnSuccess;


}

Method.Source:
public void new(MethodName _methodName, Name _title, ResourceName _icon, boolean _refreshOnSuccess)
{
    methodName			= _methodName;
    title				= _title;
    icon				= _icon;
    refreshOnSuccess	= _refreshOnSuccess;
}

public MethodName parmMethodName(MethodName	_methodName = methodName)
{
    methodName = _methodName;
    return methodName;
}

public Name parmTitle(Name	_title = title)
{
    title = _title;
    return title;
}

public ResourceName parmIcon(ResourceName	_icon = icon)
{
    icon = _icon;
    return icon;
}

public boolean parmRefreshOnSuccess(boolean	_refreshOnSuccess = refreshOnSuccess)
{
    refreshOnSuccess = _refreshOnSuccess;
    return refreshOnSuccess;
}
